def generate_quotes_json():
    dataset = []
    actions_map = {
        "success": "Identify one key goal today and take a concrete action that moves you 1% closer.",
        "career": "Invest 20 minutes today in mastering a skill or polishing a deliverable with excellence.",
        "study": "Read an insightful article or chapter on a topic you want to understand deeper.",
        "personal_growth": "Notice a limiting habit today and consciously choose an empowering alternative.",
        "leadership": "Acknowledge and encourage someone on your team or in your community today.",
        "discipline": "Complete your most important or challenging task before opening distractions.",
        "entrepreneurship": "Brainstorm one creative solution to an everyday problem and write down 3 steps.",
        "failure_resilience": "Reframe a recent setback as a valuable lesson that sharpens your resilience.",
        "happiness": "Express sincere appreciation to someone who made your day brighter."
    }

    for quote, author, cat in quotes_library:
        dataset.append({
            "quote": quote,
            "author": author,
            "category": cat,
            "tags": [cat, "inspiration", "motivation"],
            "person_story": f"{author} has inspired generations through their remarkable life journey, dedication, and enduring principles.",
            "daily_action": actions_map.get(cat, "Take one positive, intentional step today.")
        })

    output_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "quotes.json")
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(dataset, f, indent=2, ensure_ascii=False)

    print(f"Successfully generated {len(dataset)} unique quotes across 9 categories in {output_path}")

if __name__ == "__main__":
    generate_quotes_json()
